9	
10	type View = "idle" | "compiling" | "rendered";
11	const CHAR_MS = 6;
12	
13	export function Era4Runtime() {
14	  const [question, setQuestion] = useState(
15	    "What skills land junior full-stack & AI engineering roles right now?"
16	  );
17	  const [view, setView] = useState<View>("idle");
18	  const [specText, setSpecText] = useState("");
19	  const [spec, setSpec] = useState<RenderSpec | null>(null);
20	  const timer = useRef<ReturnType<typeof setInterval> | null>(null);
21	
22	  const ask = useCallback((q: string) => {
23	    if (timer.current) {
24	      clearInterval(timer.current);
25	    }
26	    const { spec: result } = generateDashboard(q);
27	    const json = JSON.stringify(result, null, 2);
28	    const reduce = typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
29	    setSpec(result);
30	    if (reduce) {
31	      setSpecText(json);
32	      setView("rendered");
33	      return;
34	    }
35	    setView("compiling");
36	    setSpecText("");
37	    let i = 0;
38	    timer.current = setInterval(() => {
39	      i += 24;
40	      setSpecText(json.slice(0, i));
41	      if (i >= json.length) {
42	        if (timer.current) {
43	          clearInterval(timer.current);
44	        }
45	        setView("rendered");
46	      }
47	    }, CHAR_MS);
48	  }, []);
49	
50	  useEffect(() => {
51	    return () => {
52	      if (timer.current) {
53	        clearInterval(timer.current);
54	      }
55	    };
56	  }, []);
57	
58	  return (
59	    <>
60	      <div className="rounded-xl border border-foreground/10 p-4 sm:p-6">
61	        <form
62	          className="flex gap-2"
63	          onSubmit={(e) => {
64	            e.preventDefault();
65	            ask(question);
66	          }}
67	        >
68	          <input
69	            className="flex-1 rounded-md border border-foreground/15 bg-background px-3 py-2 text-sm"
70	            onChange={(e) => setQuestion(e.target.value)}
71	            value={question}
72	          />
73	          <button
74	            className="rounded-md bg-foreground px-4 py-2 text-background text-sm"
75	            type="submit"
76	          >
77	            Ask
78	          </button>
79	        </form>
80	
81	        <div className="mt-3 flex flex-wrap gap-2">
82	          {INTENTS.map((intent) => (
83	            <button
84	              className="rounded-full border border-foreground/15 px-3 py-1 text-muted-foreground text-xs hover:text-foreground"
85	              key={intent.id}
86	              onClick={() => {
87	                setQuestion(intent.question);
88	                ask(intent.question);
89	              }}
90	              type="button"
91	            >
92	              {intent.label}
93	            </button>
94	          ))}
95	        </div>
96	
97	        {view === "compiling" && (
98	          <pre className="mt-5 max-h-64 overflow-auto rounded-lg border border-foreground/10 bg-muted/40 p-4 font-mono text-xs">
99	            {specText}
100	            <span className="animate-pulse">▋</span>
101	          </pre>
102	        )}
103	
104	        {view === "rendered" && spec && (
105	          <div className="mt-5 fade-in animate-in duration-300">
106	            <DashboardRenderer spec={spec} />
107	          </div>
108	        )}
109	
110	        {view === "idle" && (
111	          <p className="mt-5 text-muted-foreground text-sm">
112	            Ask a question — there is no pre-built dashboard. The UI is compiled
113	            from your question.
114	          </p>
115	        )}
116	      </div>
117	      <CompanyBrain />
118	    </>
119	  );
120	}
